getAttachmentName(mimeTreePart) {
  const { mediatype, type } = mimeTreePart.headers.contentType;
  // Early exit on multipart parts.
  if (mediatype == "multipart") {
    return null;
  }

// Skip text parts which are not clearly marked as attachments.
if (
  mediatype == "text" &&
  (!contentDisposition || !/^attachment/i.test(contentDisposition[0]))
) {
  return null;
}

return name;

if (decodeContent) {
  // Suppress content of attachments or other binary parts.
  const mediatype = mimeTreePart.headers.contentType.mediatype || "text";
  if (
    mimeTreePart.body &&
    !mimeTreePart.isAttachment &&
    mediatype == "text"
  ) {
    partObject.body = mimeTreePart.body;
  }
} else {
  partObject.rawBody = mimeTreePart.body;
}

if (decodeHeaders) {
  partObject.headers = convertHeaders(mimeTreePart);
} else {
  partObject.rawHeaders = convertRawHeaders(mimeTreePart);
}

if (mimeTreePart.isAttachment) {
  partObject.name = mimeTreePart.name || "";
}

const extractInlineTextParts = mimeTreePart => {
  const { mediatype, subtype } = mimeTreePart.headers.contentType;
  if (mediatype == "multipart") {
    for (const subPart of mimeTreePart.subParts) {
      extractInlineTextParts(subPart);
    }
  } else if (
    mediatype == "text" &&
    mimeTreePart.body &&
    !mimeTreePart.isAttachment
  ) {
    textParts.push({
      contentType: `text/${subtype}`,
      content: mimeTreePart.body,
    });
  }

add_task(
  {
    skip_if: () => IS_IMAP,
  },
  async function test_binary_attachments_as_inline_attachments() {
    const extension = ExtensionTestUtils.loadExtension({
      files: {
        "background.js": async () => {
          const [account] = await browser.accounts.list();
          const testFolder = account.folders.find(f => f.name == "test2");
          const { messages } = await browser.messages.list(testFolder.id);
          browser.test.assertEq(1, messages.length);
          const message = messages[0];

          // Request attachments.
          const attachments = await browser.messages.listAttachments(
            message.id
          );
          browser.test.assertEq(1, attachments.length);
          browser.test.assertEq("1.2", attachments[0].partName);
          browser.test.assertEq("Simple_file.pdf", attachments[0].name);
          browser.test.assertEq("inline", attachments[0].contentDisposition);

          browser.test.notifyPass("finished");
